// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // owner is initialized to address(0); only the current owner (address(0)) can transfer ownership.
        vm.assume(newOwner != address(0));
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // General rule: after transferOwnership(newOwner), the owner is exactly newOwner.
        assertTrue(c.owner() == newOwner);
    }
}
